<?php declare(strict_types=1); namespace App\People\Domain\Model; use App\People\Domain\Enum\RelationshipType; use App\People\Domain\ValueObject\PersonId; use App\People\Domain\ValueObject\RelationshipId; use App\Shared\Domain\ValueObject\AuditTimestamps; final class PersonRelationship {private function __construct(private readonly RelationshipId $id,private readonly PersonId $personId,private readonly PersonId $relatedPersonId,private RelationshipType $type,private ?\DateTimeImmutable $endedAt,private readonly AuditTimestamps $audit){} public static function create(RelationshipId $id,PersonId $personId,PersonId $related,RelationshipType $type):self{if($personId->toString()===$related->toString())throw new \InvalidArgumentException('A person cannot relate to themselves.');return new self($id,$personId,$related,$type,null,AuditTimestamps::now());} public static function reconstitute(RelationshipId $id,PersonId $personId,PersonId $related,RelationshipType $type,?\DateTimeImmutable $endedAt,AuditTimestamps $audit):self{return new self($id,$personId,$related,$type,$endedAt,$audit);} public function id():RelationshipId{return $this->id;} public function personId():PersonId{return $this->personId;} public function relatedPersonId():PersonId{return $this->relatedPersonId;} public function type():RelationshipType{return $this->type;} public function endedAt():?\DateTimeImmutable{return $this->endedAt;} public function createdAt():\DateTimeImmutable{return $this->audit->createdAt();} public function updatedAt():\DateTimeImmutable{return $this->audit->updatedAt();} public function end(\DateTimeImmutable $when):void{if($this->endedAt===null){$this->endedAt=$when;$this->audit->touch();}} }
